config.script:
self.custom.endDate   = system.date.now()
self.custom.startDate = system.date.addMonths(self.custom.endDate, -1)

# Load fleet summary for Central Region in one query (worstDev + lastEntry + completeness)
try:
	fleetDs = system.db.runNamedQuery('coolingTowerData/getFleetSummary', {})
	# Index by site name for O(1) lookup
	fleetByName = {}
	for r in range(fleetDs.getRowCount()):
		sn = fleetDs.getValueAt(r, 'siteName')
		if fleetDs.getValueAt(r, 'region') == 'Central Region':
			fleetByName[sn] = {
				'worstDev':   fleetDs.getValueAt(r, 'worstDev') or 0.0,
				'lastEntry':  system.date.format(fleetDs.getValueAt(r, 'lastEntry'), 'MM/dd/yy') if fleetDs.getValueAt(r, 'lastEntry') else 'No data',
				'siteId':     fleetDs.getValueAt(r, 'siteId'),
				'completeness': fleetDs.getValueAt(r, 'completenessPercent') or 0
			}
except Exception as e:
	system.perspective.print('Overview fleet query error: ' + str(e))
	fleetByName = {}

# Load sparklines per site (1 query each - cannot be batched)
try:
	row = fleetByName.get('Irving', {})
	self.custom.site_Irving_worstDev   = row.get('worstDev', 0.0)
	self.custom.site_Irving_lastEntry  = row.get('lastEntry', 'No data')

	# Compute paramDetail from worstDev breakdown
	paramDetail = ''
	siteId = row.get('siteId')
	if siteId and row.get('worstDev', 0) > 5:
		specDs = system.db.runNamedQuery(
			'coolingTowerData/getLatestOutOfSpec', {'siteId': siteId}
		)
		paramWorst = {}
		paramNames = {1: 'IWT', 2: 'POGT', 6: 'DAT'}
		for r in range(specDs.getRowCount()):
			dev = specDs.getValueAt(r, 'deviation')
			pid = specDs.getValueAt(r, 'parameterTypesID')
			if dev is not None:
				if pid not in paramWorst or abs(dev) > abs(paramWorst[pid]):
					paramWorst[pid] = dev
		parts = []
		for pid in [6, 1, 2]:
			if pid in paramWorst and abs(paramWorst[pid]) > 5:
				sign = '+' if paramWorst[pid] > 0 else ''
				parts.append(paramNames[pid] + ' ' + sign + '%.1f\u00b0F' % paramWorst[pid])
		paramDetail = '  '.join(parts)
	self.custom.site_Irving_paramDetail = paramDetail

	# Sparkline - 1 month of DAT actuals
	sparkDs = system.db.runNamedQuery(
		'coolingTowerData/getMonthlyApproachBySite', {'site': 'Irving'}
	)
	pts = [sparkDs.getValueAt(r, 'value') for r in range(sparkDs.getRowCount())]
	self.custom.site_Irving_points = pts if pts else []
except Exception as e:
	self.custom.site_Irving_worstDev    = 0
	self.custom.site_Irving_lastEntry   = 'Error'
	self.custom.site_Irving_paramDetail = ''
	self.custom.site_Irving_points      = []
	system.perspective.print('Overview error Irving: ' + str(e))

